    def _build_options_menu(self, menu_bar) -> None: options_menu = menu_bar.addMenu('&Options'); widget_notifications = QWidget(); layout_notifications = QHBoxLayout(); layout_notifications.setContentsMargins(10, 2, 10, 2); self.view.notifications_enabled_action = QCheckBox('Enable Windows/Mac notifications'); self.view.notifications_enabled_action.setChecked(True); layout_notifications.addWidget(self.view.notifications_enabled_action); spacer = QWidget(); spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed); layout_notifications.addWidget(spacer); widget_notifications.setLayout(layout_notifications); widget_action_notifications = QWidgetAction(self.view); widget_action_notifications.setDefaultWidget(widget_notifications); options_menu.addAction(widget_action_notifications); widget_flagfall = QWidget(); layout_flagfall = QHBoxLayout(); layout_flagfall.setContentsMargins(10, 2, 10, 2); self.view.flag_fall_action = QCheckBox('Flag fall reminder (00:00:00)'); self.view.flag_fall_action.setChecked(False); layout_flagfall.addWidget(self.view.flag_fall_action); spacer = QWidget(); spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed); layout_flagfall.addWidget(spacer); widget_flagfall.setLayout(layout_flagfall); widget_action_flagfall = QWidgetAction(self.view); widget_action_flagfall.setDefaultWidget(widget_flagfall); options_menu.addAction(widget_action_flagfall); widget_illegalmove = QWidget(); layout_illegalmove = QHBoxLayout(); layout_illegalmove.setContentsMargins(10, 2, 10, 2); self.view.illegal_move_action = QCheckBox('First illegal move'); self.view.illegal_move_action.setChecked(False); layout_illegalmove.addWidget(self.view.illegal_move_action); spacer = QWidget(); spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed); layout_illegalmove.addWidget(spacer); widget_illegalmove.setLayout(layout_illegalmove); widget_action_illegalmove = QWidgetAction(self.view); widget_action_illegalmove.setDefaultWidget(widget_illegalmove); options_menu.addAction(widget_action_illegalmove); widget_lowtime = QWidget(); layout_lowtime = QHBoxLayout(); layout_lowtime.setContentsMargins(10, 2, 10, 2); self.view.low_time_action = QCheckBox('Low time reminder if less seconds than'); self.view.low_time_action.setChecked(False); self.view.low_time_spin = QSpinBox(); self.view.low_time_spin.setRange(1, 600); self.view.low_time_spin.setValue(120); self.view.low_time_spin.setEnabled(False); layout_lowtime.addWidget(self.view.low_time_action); spacer = QWidget(); spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed); layout_lowtime.addWidget(spacer); layout_lowtime.addWidget(self.view.low_time_spin); widget_lowtime.setLayout(layout_lowtime); widget_action_lowtime = QWidgetAction(self.view); widget_action_lowtime.setDefaultWidget(widget_lowtime); options_menu.addAction(widget_action_lowtime); widget_fiftymove = QWidget(); layout_fiftymove = QHBoxLayout(); layout_fiftymove.setContentsMargins(10, 2, 10, 2); self.view.possible_fiftymove_action = QCheckBox('Possible 50-move reminder (45 moves)'); self.view.possible_fiftymove_action.setChecked(False); layout_fiftymove.addWidget(self.view.possible_fiftymove_action); spacer = QWidget(); spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed); layout_fiftymove.addWidget(spacer); widget_fiftymove.setLayout(layout_fiftymove); widget_action_fiftymove = QWidgetAction(self.view); widget_action_fiftymove.setDefaultWidget(widget_fiftymove); options_menu.addAction(widget_action_fiftymove); widget_threefold = QWidget(); layout_threefold = QHBoxLayout(); layout_threefold.setContentsMargins(10, 2, 10, 2); self.view.possible_threefold_action = QCheckBox('Possible threefold reminder (2 fold)'); self.view.possible_threefold_action.setChecked(False); layout_threefold.addWidget(self.view.possible_threefold_action); spacer = QWidget(); spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed); layout_threefold.addWidget(spacer); widget_threefold.setLayout(layout_threefold); widget_action_threefold = QWidgetAction(self.view); widget_action_threefold.setDefaultWidget(widget_threefold); options_menu.addAction(widget_action_threefold); widget_scoresheet = QWidget(); layout_scoresheet = QHBoxLayout(); layout_scoresheet.setContentsMargins(10, 2, 10, 2); self.view.scoresheet_action = QCheckBox('Scoresheet change reminder after move'); self.view.scoresheet_action.setChecked(False); self.view.scoresheet_spin = QSpinBox(); self.view.scoresheet_spin.setRange(1, 200); self.view.scoresheet_spin.setValue(55); self.view.scoresheet_spin.setEnabled(False); layout_scoresheet.addWidget(self.view.scoresheet_action); spacer = QWidget(); spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed); layout_scoresheet.addWidget(spacer); layout_scoresheet.addWidget(self.view.scoresheet_spin); widget_scoresheet.setLayout(layout_scoresheet); widget_action_scoresheet = QWidgetAction(self.view); widget_action_scoresheet.setDefaultWidget(widget_scoresheet); options_menu.addAction(widget_action_scoresheet); widget_sofia = QWidget(); layout_sofia = QHBoxLayout(); layout_sofia.setContentsMargins(10, 2, 10, 2); self.view.sofia_action = QCheckBox('Sofia rule - draw before move completed'); self.view.sofia_action.setChecked(False); self.view.sofia_spin = QSpinBox(); self.view.sofia_spin.setRange(1, 200); self.view.sofia_spin.setValue(30); self.view.sofia_spin.setEnabled(False); layout_sofia.addWidget(self.view.sofia_action); spacer = QWidget(); spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed); layout_sofia.addWidget(spacer); layout_sofia.addWidget(self.view.sofia_spin); widget_sofia.setLayout(layout_sofia); widget_action_sofia = QWidgetAction(self.view); widget_action_sofia.setDefaultWidget(widget_sofia); options_menu.addAction(widget_action_sofia); widget_timecontrol = QWidget(); layout_timecontrol = QHBoxLayout(); layout_timecontrol.setContentsMargins(10, 2, 10, 2); self.view.timecontrol_action = QCheckBox('Time control reminder after move'); self.view.timecontrol_action.setChecked(False); self.view.timecontrol_spin = QSpinBox(); self.view.timecontrol_spin.setRange(1, 200); self.view.timecontrol_spin.setValue(38); self.view.timecontrol_spin.setEnabled(False); layout_timecontrol.addWidget(self.view.timecontrol_action); spacer = QWidget(); spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed); layout_timecontrol.addWidget(spacer); layout_timecontrol.addWidget(self.view.timecontrol_spin); widget_timecontrol.setLayout(layout_timecontrol); widget_action_timecontrol = QWidgetAction(self.view); widget_action_timecontrol.setDefaultWidget(widget_timecontrol); options_menu.addAction(widget_action_timecontrol)
    def _build_help_menu(self, menu_bar) -> None:
        about_menu = menu_bar.addMenu('&Help')
        
        about_action = QAction('About', self.view)
        about_menu.addAction(about_action)
        about_action.triggered.connect(self.view.controller.on_about_clicked)
        
        user_manual_action = QAction('User Manual', self.view)
        about_menu.addAction(user_manual_action)
        user_manual_action.triggered.connect(self.view.controller.on_user_manual_clicked)
